+    assert!(r_locked.strict().is_err());
+
+    let angled =
+        PartInput::closed("bar", 1, bar, vec![]).with_rotation(RotationMode::FixedStep(45.0));
+    let r_angled = nest(&sheet, &[angled]).expect("45 deg rotation fits");
+    assert_eq!(r_angled.total_placed, 1);
+}
